cat > .git/first-para.mjs <<'EOF'
import fs from 'node:fs'; import path from 'node:path';
const dir = process.argv[2];
const files = fs.existsSync(dir) ? fs.readdirSync(dir).filter((f) => /\.mdx?$/.test(f)) : [];
if (files.length !== 1) { console.log(`expected one page in ${dir}, found ${files.length}`); process.exit(1); }
let t = fs.readFileSync(path.join(dir, files[0]), 'utf8').replace(/\r\n/g, '\n');
t = t.replace(/^---\n[\s\S]*?\n---\n/, '').replace(/\{\/\*[\s\S]*?\*\/\}/g, '');
const para = t.split(/\n\s*\n/).map((p) => p.trim()).find((p) => p && !/^(#|import |export |<|!\[|:::|```|\||[-*] |\d+\. )/.test(p));
console.log(`first paragraph: ${para}`);
if (!para) process.exit(1);
if (/^[«"]?Транзакці[яї]\s*[—–-]\s/.test(para)) { console.log('opens with a bare definition'); process.exit(1); }
EOF
